  4304	reduce_string_list(Node* node)
  4305	{
  4306	  int r = 0;
  4307	
  4308	  switch (NODE_TYPE(node)) {
  4309	  case NODE_LIST:
  4310	    {
  4311	      Node* prev;
  4312	      Node* curr;
  4313	      Node* prev_node;
  4314	      Node* next_node;
  4315	
  4316	      prev = NULL_NODE;
  4317	      do {
  4318	        next_node = NODE_CDR(node);
  4319	        curr = NODE_CAR(node);
  4320	        if (NODE_TYPE(curr) == NODE_STRING) {
  4321	          if (IS_NULL(prev)
  4322	              || STR_(curr)->flag  != STR_(prev)->flag
  4323	              || NODE_STATUS(curr) != NODE_STATUS(prev)) {
  4324	            prev = curr;
  4325	            prev_node = node;
  4326	          }
  4327	          else {
  4328	            r = node_str_node_cat(prev, curr);
  4329	            if (r != 0) return r;
  4330	            remove_from_list(prev_node, node);
  4331	            onig_node_free(node);
  4332	          }
  4333	        }
  4334	        else {
  4335	          prev = NULL_NODE;
  4336	          prev_node = node;
  4337	        }
  4338	
  4339	        node = next_node;
  4340	      } while (r == 0 && IS_NOT_NULL(node));
  4341	    }
  4342	    break;
  4343	
  4344	  case NODE_ALT:
  4345	    do {
  4346	      r = reduce_string_list(NODE_CAR(node));
  4347	    } while (r == 0 && IS_NOT_NULL(node = NODE_CDR(node)));
  4348	    break;
  4349	
  4350	  case NODE_ANCHOR:
  4351	    if (IS_NULL(NODE_BODY(node)))
  4352	      break;
  4353	    /* fall */
  4354	  case NODE_QUANT:
  4355	    r = reduce_string_list(NODE_BODY(node));
  4356	    break;
  4357	
  4358	  case NODE_BAG:
  4359	    {
  4360	      BagNode* en = BAG_(node);
  4361	
  4362	      r = reduce_string_list(NODE_BODY(node));
  4363	      if (r != 0) return r;
  4364	
  4365	      if (en->type == BAG_IF_ELSE) {
  4366	        if (IS_NOT_NULL(en->te.Then)) {
  4367	          r = reduce_string_list(en->te.Then);
  4368	          if (r != 0) return r;
  4369	        }
  4370	        if (IS_NOT_NULL(en->te.Else)) {
  4371	          r = reduce_string_list(en->te.Else);
  4372	          if (r != 0) return r;
  4373	        }
  4374	      }
  4375	    }
  4376	    break;
  4377	
  4378	  default:
  4379	    break;
  4380	  }
  4381	
  4382	  return r;
  4383	}
